 text.push_str("\nPrimary32 is a descriptive scaling control. Qualification requires primary improvements at both64/96 and nonregression of every other target case. The complete [analysis](artifacts/analysis.json) retains all block ratios, resource observations, profiles and failures. Best-tested worker counts below are descriptive and are not an adopted worker-selection policy.\n\n## Best tested configurations and supplied M5 references\n\nWhole-process RSS includes loading/setup/primes. It is neither incremental scratch nor minimum RAM. Summed CPU includes coordination and is not an operation count. M5CPU/Metal values are supplied historical references. Candidate ratios do not establish adoption.\n\n| Circuit | Accepted ms / workers | Candidate ms / workers | Aeglos ms / workers | Accepted / candidate / Aeglos RSS MiB | Supplied M5 CPU / Metal ms | Candidate CPU / Metal speedup |\n|---|---:|---:|---:|---:|---:|---:|\n");
 let mut targets=0;for shape in ["1x2","2x2","4x2","8x2","12x2","16x2","24x2","merge-24x1","merge-54x1"]{let cs:Vec<_>=a["cases"].as_object().unwrap().values().filter(|c|c["shape"]==shape).collect();let best=|mode:&str|*cs.iter().min_by(|a,b|a["engines"][mode]["request_ms"].as_f64().unwrap().total_cmp(&b["engines"][mode]["request_ms"].as_f64().unwrap())).unwrap();let z=best("accepted");let on=best("on");let ag=best("aeglos");let mode=|c:&Value,m:&str|format!("{:.3} /{}",c["engines"][m]["request_ms"].as_f64().unwrap(),c["workers"]);let rss=|c:&Value,m:&str|c["engines"][m]["maximum_whole_process_RSS_mib"].as_f64().unwrap();let reference=&on["reference"];let (refs,speed)=if reference.is_object(){let ms=on["engines"]["on"]["request_ms"].as_f64().unwrap();let cpu=reference["cpu_ms"].as_f64().unwrap()/ms;let metal=reference["metal_ms"].as_f64().unwrap()/ms;if cpu>=10.{targets+=1;}(format!("{:.0} /{:.0}",reference["cpu_ms"].as_f64().unwrap(),reference["metal_ms"].as_f64().unwrap()),format!("{cpu:.2}× /{metal:.2}×"))}else{("not supplied".into(),"—".into())};writeln!(text,"|{shape}|{}|{}|{}|{:.1} /{:.1} /{:.1}|{refs}|{speed}|",mode(z,"accepted"),mode(on,"on"),mode(ag,"aeglos"),rss(z,"accepted"),rss(on,"on"),rss(ag,"aeglos")).unwrap();}
